/*
 * A007694  Numbers k such that phi(k) divides k.
 * https://oeis.org/A007694
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, nice, easy
 * Formula:   a(1) = 1; a(n) = 2*A003586(n-1) for n > 1, where A003586 lists
 *            the 3-smooth numbers 2^i*3^j in increasing order (generated by
 *            merging the multiples of 2 and 3)
 * Range:     u8 n <= 22, u16 n <= 84, u32 n <= 329, u64 n <= 1304,
 *            u128 n <= 5192, big any n
 * Validated: standard, pass, 75 terms through n = 9298 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/mem.h"

static seq_t *alloc_zero(idx_t len) {
    seq_t *p = mem_new(seq_t, (size_t)len);
    for (idx_t i = 0; i < len; i++) p[i] = 0;
    return p;
}

static void release(seq_t *v, idx_t len) {
    for (idx_t i = 0; i < len; i++) v[i] = 0;
    mem_free(v);
}

seq_t a(idx_t n) {
    if (n == 1) return 1;

    idx_t m = n - 1;
    seq_t *h = alloc_zero(m);
    h[0] = 1;

    idx_t i2 = 0, i3 = 0;
    for (idx_t i = 1; i < m; i++) {
        seq_t next2 = h[i2] * 2;
        seq_t next3 = h[i3] * 3;
        if (next2 <= next3) {
            h[i] = next2;
            if (next2 == next3) i3++;
            i2++;
        } else {
            h[i] = next3;
            i3++;
        }
    }

    seq_t result = h[m - 1] * 2;
    release(h, m);
    return result;
}
